components.css:
.ds-confidential-plate{position:relative;width:360px;height:225px;border-radius:24px;overflow:hidden;border:1px solid var(--color-border);background:radial-gradient(120% 130% at 50% -10%, color-mix(in srgb, var(--color-foreground) 6%, transparent), transparent 60%), var(--color-secondary-background);isolation:isolate;font-family:JetBrains Mono Variable, JetBrains Mono, ui-monospace, monospace}
.ds-cp-screen{position:absolute;inset:27px 29px;display:flex;flex-direction:column;gap:12px;padding:15px;border-radius:12px;border:1px solid color-mix(in srgb, var(--color-foreground) 10%, transparent);background:color-mix(in srgb, var(--color-foreground) 5%, transparent);filter:blur(2.4px);opacity:.9}
.ds-cp-chrome{display:flex;align-items:center;gap:7px}
.ds-cp-chrome span{width:8px;height:8px;border-radius:50%;background:color-mix(in srgb, var(--color-foreground) 22%, transparent)}
.ds-cp-chrome i{margin-left:6px;flex:1;max-width:55%;height:11px;border-radius:999px;background:color-mix(in srgb, var(--color-foreground) 12%, transparent)}
.ds-cp-body{display:flex;gap:14px;flex:1;min-height:0}
.ds-cp-side{display:flex;flex-direction:column;gap:10px;width:22%;padding-top:3px}
.ds-cp-side b{height:9px;border-radius:999px;background:color-mix(in srgb, var(--color-foreground) 15%, transparent)}
.ds-cp-side b.s78{width:78%}.ds-cp-side b.s64{width:64%}
.ds-cp-main{display:flex;flex-direction:column;gap:11px;flex:1;min-width:0}
.ds-cp-main u{height:10px;border-radius:999px;background:color-mix(in srgb, var(--color-foreground) 20%, transparent)}
.ds-cp-main u.w80{width:80%}.ds-cp-main u.w60{width:58%}.ds-cp-main u.w70{width:70%}
.ds-cp-chart{margin-top:auto;display:flex;align-items:flex-end;gap:8px;height:34%}
.ds-cp-chart s{flex:1;border-radius:3px 3px 0 0;background:color-mix(in srgb, var(--color-foreground) 16%, transparent)}
.ds-cp-scrim{position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(90% 70% at 50% 46%, transparent, color-mix(in srgb, var(--color-background) 30%, transparent) 100%), repeating-linear-gradient(-45deg, transparent 0 7px, color-mix(in srgb, var(--color-foreground) 4%, transparent) 7px 8px);box-shadow:inset 0 0 0 1px color-mix(in srgb, var(--color-foreground) 6%, transparent)}
.ds-cp-marker{position:absolute;inset:auto 0 0 0;z-index:2;display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:22px}
.ds-cp-pill{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border-radius:999px;border:1px solid color-mix(in srgb, var(--color-foreground) 26%, transparent);background:color-mix(in srgb, var(--color-background) 62%, transparent);backdrop-filter:blur(6px);font-size:14px;font-weight:600;letter-spacing:.16em;color:hsl(var(--foreground))}
.ds-cp-pill svg{color:color-mix(in srgb, var(--color-foreground) 62%, transparent)}
.ds-cp-note{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:color-mix(in srgb, var(--color-foreground) 62%, transparent)}
